import { COMMERCIAL_RESULTS_PAGE_NAME } from './constants';

/**
 * Commercial Results "Other Filters" — flat preset fields that do not drive
 * hierarchy (zone → country → brand → sku). Changing them must not reset brands.
 */
export const COMMERCIAL_RESULTS_NON_CASCADING_FORM_KEYS = new Set([
  'category',
  'non_alcoholic',
  'pack_type',
  'growth_levers',
  'beer_price_segment',
  'portfolios',
  'channel',
]);

export function shouldSkipCommercialResultsFormCascade(
  pageName: string | null,
  fieldKey: string,
): boolean {
  return (
    pageName === COMMERCIAL_RESULTS_PAGE_NAME &&
    COMMERCIAL_RESULTS_NON_CASCADING_FORM_KEYS.has(fieldKey)
  );
}
